<?php
require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../includes/auth.php';require_login();
$page_title='My Claims';$s=$pdo->prepare("SELECT c.*,st.name status_name FROM claims c JOIN statuses st ON st.id=c.status_id WHERE c.user_id=? ORDER BY c.created_at DESC");$s->execute([$_SESSION['user']['id']]);$claims=$s->fetchAll();
include __DIR__.'/../includes/header.php';?><div class="py-4"><h2 class="section-title mb-4">My Claims</h2><div class="glass-panel table-wrap"><table class="table align-middle"><thead><tr><th>Type</th><th>Item ID</th><th>Details</th><th>Status</th><th>Submitted</th></tr></thead><tbody><?php foreach($claims as $c):?><tr><td><?=e(ucfirst($c['item_type']))?></td><td>#<?=$c['item_id']?></td><td><?=e(mb_strimwidth($c['details'],0,90,'…'))?></td><td><span class="badge badge-soft"><?=e($c['status_name'])?></span></td><td><?=date('d M Y',strtotime($c['created_at']))?></td></tr><?php endforeach;?></tbody></table></div></div><?php include __DIR__.'/../includes/footer.php';?>